export default function config({ spreadsheetId, sheetName }) {
  if (
    typeof spreadsheetId !== "string" ||
    !spreadsheetId ||
    spreadsheetId.startsWith("YOUR_") ||
    typeof sheetName !== "string" ||
    !sheetName ||
    sheetName.startsWith("YOUR_")
  )
    throw Error("Configure the spreadsheet and sheet name");
  return { spreadsheetId, sheetName, range: "'" + sheetName.replaceAll("'", "''") + "'" };
}

