export default function names({ sheetIdByName, sheetName, spreadsheetId, range }) {
  const sheetId = sheetIdByName?.[sheetName];
  if (!Number.isInteger(sheetId) || sheetId < 0) throw Error("Sheet not found");
  return { sheetId, spreadsheetId, range };
}

