export default function select({ values }) {
  if (!Array.isArray(values) || !Array.isArray(values[0])) throw Error("A header row is required");
  const header = values[0],
    indices = header.flatMap((v, i) => (v === "tweet" ? [i] : []));
  if (indices.length !== 1) throw Error("Expected exactly one tweet column");
  const col = indices[0],
    items = [];
  for (let i = 1; i < values.length; i++) {
    const row = values[i];
    if (!Array.isArray(row)) throw Error("Invalid sheet row");
    if (row.length === 0) continue;
    const text = row[col];
    if (typeof text !== "string" || !text.trim()) throw Error("A populated row lacks tweet text");
    items.push({ text, rowIndex: i });
  }
  return { snapshot: values, items, hasItems: items.length > 0 };
}

