export default function next({ items, previous }) {
  let index = previous?.index ?? 0;
  if (index >= items.length) return { state: { index }, more: false, text: "", rowIndex: 0 };
  return {
    state: { index: index + 1 },
    more: true,
    text: items[index].text,
    rowIndex: items[index].rowIndex,
  };
}

