export default function check({ snapshot, values, items, sheetId }) {
  if (JSON.stringify(snapshot) !== JSON.stringify(values))
    throw Error("Sheet changed after posting; no rows deleted");
  if (!Number.isInteger(sheetId) || sheetId < 0) throw Error("Invalid sheet ID");
  return { items: [...items].reverse().map((x) => ({ rowIndex: x.rowIndex, sheetId })) };
}

