export default function next({ items, previous }) {
  let i = previous?.index ?? 0;
  if (i >= items.length)
    return {
      state: { index: i },
      more: false,
      request: { range: { sheetId: 0, dimension: "ROWS", startIndex: 1, endIndex: 2 } },
    };
  const x = items[i];
  return {
    state: { index: i + 1 },
    more: true,
    request: {
      range: {
        sheetId: x.sheetId,
        dimension: "ROWS",
        startIndex: x.rowIndex,
        endIndex: x.rowIndex + 1,
      },
    },
  };
}
